package br.gov.ma.pacodolumiar.semed.tecnico;
import android.app.*;import android.app.job.*;import android.content.*;import org.json.*;
public class NoticeJob extends JobService {
 private volatile boolean cancelled;
 @Override public boolean onStartJob(JobParameters params){cancelled=false;android.webkit.CookieManager.getInstance();new Thread(()->{try{JSONObject data=Api.call("/api/technician/notifications",null,null);if(data.optInt("_http")==401||data.optInt("_http")==403){((JobScheduler)getSystemService(JOB_SCHEDULER_SERVICE)).cancel(105);return;}if(data.optInt("_http")!=200||cancelled)return;JSONArray notices=data.getJSONArray("notifications");if(notices.length()==0)return;long newest=notices.getJSONObject(0).getLong("id");SharedPreferences p=getSharedPreferences("notices",MODE_PRIVATE);if(newest>p.getLong("last",0)&&data.optInt("unread")>0){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("demands","Atualizações dos atendimentos",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(this,1,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);nm.notify(106,new Notification.Builder(this,"demands").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("SEMED · atualização de atendimento").setContentText("Abra o aplicativo para conferir suas demandas e a sequência.").setContentIntent(open).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE).build());p.edit().putLong("last",newest).apply();}}catch(Exception ignored){}finally{jobFinished(params,false);}},"SEMED-notices").start();return true;}
 @Override public boolean onStopJob(JobParameters params){cancelled=true;return true;}
}
